package com.alsafa.native4;

import android.app.Activity;import android.app.AlertDialog;import android.text.InputType;import android.view.Gravity;import android.view.View;import android.view.ViewGroup;import android.widget.ArrayAdapter;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.Spinner;import android.widget.TextView;import com.alsafa.native4.core.AccountingChoices;import com.alsafa.native4.core.Native4BackgroundSync;import com.alsafa.native4.core.Native4Services;import com.alsafa.native4.core.OnlineSaleSettlementStore;import com.alsafa.native4.core.SplitPaymentStore;import java.util.ArrayList;import java.util.List;
/** Online orders: independent merchandise/shipping currencies, split deposits, later collections, expenses and explicit final-price edits. */
public final class OnlineSalePanelBinder {
 private final Activity a;private final Native4Services services;private final TextView status;private final LinearLayout panel,initialRows,collectRows;private final EditText saleId,merchandise,shipping,settlementId,expenseAmount,expenseType,expenseNotes,finalPrice,adjustReason;private final Spinner merchandiseCurrency,shippingCurrency,shippingPayer,shippingStatus,shippingPaidBy,shippingAccount,expenseCurrency,expenseAccount;
 public OnlineSalePanelBinder(Activity a,Native4Services services,TextView status,ViewGroup host){this.a=a;this.services=services;this.status=status;panel=new LinearLayout(a);panel.setOrientation(LinearLayout.VERTICAL);panel.setVisibility(View.GONE);title("بيع الإنترنت — الشحن والدفعات والتحصيل");saleId=field("مرجع فاتورة البيع",InputType.TYPE_CLASS_TEXT);merchandise=field("قيمة المنتجات",numType());merchandiseCurrency=currency();shipping=field("أجرة الشحن",numType());shippingCurrency=currency();shippingPayer=spinner(new String[]{"المشتري يتحمل الشحن","الصفا يتحمل الشحن"});shippingStatus=spinner(new String[]{"غير مدفوع","مدفوع"});shippingPaidBy=spinner(new String[]{"العميل","الصفا","شركة الشحن"});shippingAccount=account(true);add(saleId,merchandise,merchandiseCurrency,shipping,shippingCurrency,shippingPayer,shippingStatus,shippingPaidBy,shippingAccount);title("العربون / الدفعات الأولية");initialRows=rows();button("+ إضافة دفعة",v->addPayment(initialRows));addPayment(initialRows);button("تثبيت تسوية بيع الإنترنت",v->create());title("تحصيل لاحق");settlementId=field("مرجع التسوية",InputType.TYPE_CLASS_TEXT);panel.addView(settlementId);collectRows=rows();addPayment(collectRows);button("+ إضافة دفعة تحصيل",v->addPayment(collectRows));button("تسجيل التحصيل",v->collect());title("مصروف على الطلب");expenseType=field("نوع المصروف: تغليف / توصيل / غيره",InputType.TYPE_CLASS_TEXT);expenseAmount=field("قيمة المصروف",numType());expenseCurrency=currency();expenseAccount=account(false);expenseNotes=field("ملاحظات المصروف",InputType.TYPE_CLASS_TEXT);add(expenseType,expenseAmount,expenseCurrency,expenseAccount,expenseNotes);button("تسجيل المصروف",v->expense());title("تعديل السعر النهائي بعد المفاصلة");finalPrice=field("السعر النهائي للمنتجات",numType());adjustReason=field("سبب التعديل",InputType.TYPE_CLASS_TEXT);add(finalPrice,adjustReason);button("تعديل السعر النهائي",v->confirmAdjust());host.addView(panel);}
 public void show(boolean visible){panel.setVisibility(visible?View.VISIBLE:View.GONE);}private void create(){try{String mc=code(merchandiseCurrency),sc=code(shippingCurrency),ss=shippingStatus.getSelectedItemPosition()==1?"PAID":"UNPAID",sp=shippingPaidBy.getSelectedItemPosition()==0?"CUSTOMER":shippingPaidBy.getSelectedItemPosition()==1?"ALSAFA":"CARRIER",sa=shippingAccount.getSelectedItemPosition()==0?"":accountCode(shippingAccount.getSelectedItemPosition()-1);OnlineSaleSettlementStore.Result r=services.onlineSales.create(saleId.getText().toString(),num(merchandise),mc,num(shipping),sc,shippingPayer.getSelectedItemPosition()==0,read(initialRows),ss,sp,sa);settlementId.setText(r.settlementId);sync();status.setText("✓ تم إنشاء الطلب — المطلوب "+fmt(r.totalDueUsd)+" USD — المدفوع "+fmt(r.paidTotalUsd)+" — المتبقي "+fmt(r.remainingUsd));}catch(Exception e){error("لم يُحفظ طلب الإنترنت",e);}}
 private void collect(){try{OnlineSaleSettlementStore.Result r=services.onlineSales.collect(settlementId.getText().toString(),read(collectRows));sync();collectRows.removeAllViews();addPayment(collectRows);status.setText("✓ التحصيل — المدفوع "+fmt(r.paidTotalUsd)+" USD — المتبقي "+fmt(r.remainingUsd));}catch(Exception e){error("لم يُحفظ التحصيل",e);}}
 private void expense(){try{String id=services.onlineSales.addExpense(settlementId.getText().toString(),expenseType.getText().toString(),num(expenseAmount),code(expenseCurrency),"ALSAFA",accountCode(expenseAccount.getSelectedItemPosition()),expenseNotes.getText().toString());sync();expenseAmount.setText("");status.setText("✓ تم تسجيل مصروف الطلب — "+id);}catch(Exception e){error("لم يُحفظ المصروف",e);}}
 private void confirmAdjust(){try{double p=num(finalPrice);String why=adjustReason.getText().toString().trim();if(why.isEmpty())throw new IllegalArgumentException("سبب تعديل السعر مطلوب");new AlertDialog.Builder(a).setTitle("تأكيد تعديل السعر").setMessage("سيتم تغيير السعر النهائي للمنتجات إلى "+fmt(p)+" بعملة الفاتورة، وسيُسجل الفرق كحسم للعميل أو زيادة. الدفعات الجزئية لا تُسجل من هنا. هل تريد المتابعة؟").setNegativeButton("رجوع",null).setPositiveButton("تأكيد",(d,w)->adjust(p,why)).show();}catch(Exception e){error("تعذر تعديل السعر",e);}}
 private void adjust(double p,String why){try{OnlineSaleSettlementStore.Result r=services.onlineSales.adjustFinalMerchandisePrice(settlementId.getText().toString(),p,true,why);sync();status.setText("✓ السعر النهائي عُدّل — النوع "+r.adjustmentKind+" — الحسم "+fmt(r.customerDiscount)+" — المتبقي "+fmt(r.remainingUsd)+" USD");}catch(Exception e){error("لم يُعدل السعر",e);}}
 private void addPayment(LinearLayout host){LinearLayout box=new LinearLayout(a);box.setOrientation(LinearLayout.VERTICAL);EditText amount=field("المبلغ",numType());Spinner cur=currency(),acc=account(false);Button del=new Button(a);del.setText("حذف الدفعة");del.setOnClickListener(v->{if(host.getChildCount()>1)host.removeView(box);else amount.setText("");});box.addView(amount);box.addView(cur);box.addView(acc);box.addView(del);box.setTag(new PV(amount,cur,acc));host.addView(box);}private List<SplitPaymentStore.Payment> read(LinearLayout host){List<SplitPaymentStore.Payment> out=new ArrayList<>();for(int i=0;i<host.getChildCount();i++){PV p=(PV)host.getChildAt(i).getTag();String raw=p.amount.getText().toString().trim();if(raw.isEmpty())continue;String cur=code(p.currency),acc=accountCode(p.account.getSelectedItemPosition()),method="SHAM_CASH".equals(acc)?"SHAM_CASH":"CASH";out.add(new SplitPaymentStore.Payment(Double.parseDouble(raw),cur,method,acc));}return out;}
 private LinearLayout rows(){LinearLayout x=new LinearLayout(a);x.setOrientation(LinearLayout.VERTICAL);panel.addView(x);return x;}private Spinner currency(){return spinner(AccountingChoices.CURRENCY_LABELS);}private Spinner account(boolean allowNone){return spinner(allowNone?new String[]{"لا توجد خزنة الآن","الدرج","شام كاش","الخزنة الخارجية","البنك"}:new String[]{"الدرج","شام كاش","الخزنة الخارجية","البنك"});}private static String accountCode(int p){if(p==1)return "SHAM_CASH";if(p==2)return "EXTERNAL";if(p==3)return "BANK";return "MAIN";}private String code(Spinner s){return AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,s.getSelectedItemPosition());}
 private void title(String s){TextView t=new TextView(a);t.setText(s);t.setTextSize(18);t.setGravity(Gravity.END);panel.addView(t);}private void button(String s,View.OnClickListener l){Button b=new Button(a);b.setText(s);b.setOnClickListener(l);panel.addView(b);}private void add(View...vs){for(View v:vs)panel.addView(v);}private EditText field(String hint,int type){EditText e=new EditText(a);e.setHint(hint);e.setInputType(type);e.setGravity(Gravity.END);e.setLayoutParams(new ViewGroup.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));return e;}private Spinner spinner(String[] labels){Spinner s=new Spinner(a);s.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));return s;}private static int numType(){return InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL;}private static double num(EditText e){String s=e.getText().toString().trim();return s.isEmpty()?0:Double.parseDouble(s);}private void sync(){Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();}private void error(String p,Exception e){status.setText(p+": "+(e.getMessage()==null?e.getClass().getSimpleName():e.getMessage()));}private static String fmt(double v){return String.format(java.util.Locale.US,"%.2f",v);}private static final class PV{final EditText amount;final Spinner currency,account;PV(EditText a,Spinner c,Spinner x){amount=a;currency=c;account=x;}}
}
